import { resolveMediaSrc } from './resolve.ts';
import { WALLET_ICON_DERIVATIVES } from './wallet-icons.generated.ts';

/**
 * Wallet-facing image URL for an on-chain logo URI (EIP-747 `image`).
 *
 * Resolution order — every launched token must keep wallet metadata:
 *   1. Registered derivative: committed content-addressed square-PNG
 *      (`/wallet/<sha256>.png`, generated by scripts/wallet-icons) served from the
 *      public origin. Wallet icon clients are plain <img> fetchers, and creator
 *      uploads can be animated non-square GIFs, so registered sources get the
 *      static derivative.
 *   2. Registry miss: the existing media resolver maps the on-chain URI to a
 *      browser-loadable URL (ipfs:// → IPFS gateway, ar:// → arweave.net, https
 *      passthrough, dead quick-tunnel media → same-origin path). Same-origin
 *      relative paths are absolutized against the public origin; anything that
 *      still is not fetchable https is dropped — never send a wallet a URL it
 *      cannot fetch.
 */
const env = (import.meta as unknown as { env?: Record<string, string | undefined> }).env;
const PUBLIC_ORIGIN = env?.VITE_PUBLIC_ORIGIN?.replace(/\/+$/, '') || 'https://retropick.xyz';

export function resolveWalletImage(logo: string | null | undefined): string | null {
  const value = logo?.trim();
  if (!value) return null;
  const derivative = WALLET_ICON_DERIVATIVES[value];
  if (derivative) return `${PUBLIC_ORIGIN}${derivative}`;
  const resolved = resolveMediaSrc(value);
  if (!resolved) return null;
  if (resolved.startsWith('https://')) return resolved;
  // Quick-tunnel era media rewrites to a same-origin content-addressed path that is
  // public through the staging rewrite in production.
  if (resolved.startsWith('/')) return `${PUBLIC_ORIGIN}${resolved}`;
  return null;
}
